-- Production PostgreSQL/Supabase reference schema for LEVELUP AI.
-- The verified Demo runtime uses data/db.json so it can run with zero external services.
create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),email text unique not null,role text not null default 'user',email_verified boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists profiles(user_id uuid primary key references users(id),display_name text not null,birth_year int,plan_id text not null default 'free',xp int not null default 0,coins int not null default 0,level int not null default 1,streak int not null default 0,privacy text not null default 'private',locale text not null default 'he',coach_style text not null default 'supportive',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists parental_consents(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id),guardian_email text,status text not null,verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists plans(id text primary key,name text not null,price_nis int not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists plan_features(plan_id text references plans(id),feature_key text not null,enabled boolean not null,primary key(plan_id,feature_key));
create table if not exists subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),plan_id text references plans(id),status text not null,starts_at timestamptz,ends_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists learning_paths(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,category text,difficulty text,goal text,creator_id uuid references users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists path_enrollments(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),path_id uuid references learning_paths(id),progress int not null default 0,active boolean not null default true,target_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists chapters(id uuid primary key default gen_random_uuid(),path_id uuid references learning_paths(id),title text not null,position int not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists lessons(id uuid primary key default gen_random_uuid(),chapter_id uuid references chapters(id),title text not null,position int not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists tasks(id uuid primary key default gen_random_uuid(),chapter_id uuid references chapters(id),title text not null,kind text not null default 'practice',xp int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists task_submissions(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),task_id uuid references tasks(id),payload jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists ai_coach_messages(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),role text not null,content text not null,created_at timestamptz not null default now());
create table if not exists skills(id uuid primary key default gen_random_uuid(),name text unique not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists user_skills(user_id uuid references users(id),skill_id uuid references skills(id),score numeric not null default 0,updated_at timestamptz not null default now(),primary key(user_id,skill_id));
create table if not exists xp_events(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),amount int not null,reason text not null,idempotency_key text unique,created_at timestamptz not null default now());
create table if not exists achievements(id text primary key,title text not null,description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists user_achievements(user_id uuid references users(id),achievement_id text references achievements(id),created_at timestamptz not null default now(),primary key(user_id,achievement_id));
create table if not exists streaks(user_id uuid primary key references users(id),current int not null default 0,best int not null default 0,last_date date,updated_at timestamptz not null default now());
create table if not exists friendships(id uuid primary key default gen_random_uuid(),requester_id uuid references users(id),addressee_id uuid references users(id),status text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists challenges(id uuid primary key default gen_random_uuid(),creator_id uuid references users(id),kind text,title text,status text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists challenge_participants(challenge_id uuid references challenges(id),user_id uuid references users(id),score int,created_at timestamptz not null default now(),primary key(challenge_id,user_id));
create table if not exists marketplace_paths(id uuid primary key default gen_random_uuid(),path_id uuid references learning_paths(id),creator_id uuid references users(id),price_nis int not null default 0,status text not null default 'pending',rating numeric,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists marketplace_sales(id uuid primary key default gen_random_uuid(),marketplace_path_id uuid references marketplace_paths(id),buyer_id uuid references users(id),price_nis int not null,commission_nis int not null default 0,created_at timestamptz not null default now());
create table if not exists reviews(id uuid primary key default gen_random_uuid(),marketplace_path_id uuid references marketplace_paths(id),user_id uuid references users(id),rating int not null check(rating between 1 and 5),body text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists favorites(user_id uuid references users(id),marketplace_path_id uuid references marketplace_paths(id),created_at timestamptz not null default now(),primary key(user_id,marketplace_path_id));
create table if not exists daily_games(id uuid primary key default gen_random_uuid(),daily_game_id text unique not null,date date not null,seed bigint not null,version int not null,game_mode text not null,world_theme text not null,difficulty int not null,config jsonb not null,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists daily_game_templates(id uuid primary key default gen_random_uuid(),game_mode text not null,version int not null,config jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists daily_game_questions(id uuid primary key default gen_random_uuid(),daily_game_id uuid references daily_games(id),question jsonb not null,position int not null,created_at timestamptz not null default now());
create table if not exists daily_game_attempts(id uuid primary key default gen_random_uuid(),daily_game_id uuid references daily_games(id),user_id uuid references users(id),started_at timestamptz not null,finished_at timestamptz,score int,suspicious boolean not null default false,created_at timestamptz not null default now());
create table if not exists game_events(id uuid primary key default gen_random_uuid(),attempt_id uuid references daily_game_attempts(id),sequence int not null,event jsonb not null,created_at timestamptz not null default now());
create table if not exists leaderboards(id uuid primary key default gen_random_uuid(),date date not null,group_key text not null,user_id uuid references users(id),score int not null,created_at timestamptz not null default now(),unique(date,group_key,user_id));
create table if not exists cosmetic_items(id uuid primary key default gen_random_uuid(),name text not null,kind text not null,minimum_plan text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists user_inventory(user_id uuid references users(id),item_id uuid references cosmetic_items(id),unlocked_at timestamptz not null default now(),primary key(user_id,item_id));
create table if not exists orders(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),plan_id text,price_nis int not null,status text not null,payment_method text not null,approved_by uuid references users(id),approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists payment_proofs(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id),user_id uuid references users(id),storage_key text not null,mime text not null,size int not null,created_at timestamptz not null default now());
create table if not exists notifications(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),title text not null,body text,read boolean not null default false,created_at timestamptz not null default now());
create table if not exists reports(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),target_type text not null,target_id text not null,reason text,status text not null default 'open',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists admin_actions(id uuid primary key default gen_random_uuid(),actor_id uuid references users(id),action text not null,target_type text,target_id text,meta jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists idx_enrollments_user_active on path_enrollments(user_id,active) where deleted_at is null;
create index if not exists idx_attempts_user_date on daily_game_attempts(user_id,started_at desc);
create index if not exists idx_orders_status on orders(status,created_at desc);
create index if not exists idx_reports_status on reports(status,created_at desc);
-- Supabase RLS examples (enable and expand for production):
alter table profiles enable row level security;
alter table task_submissions enable row level security;
alter table path_enrollments enable row level security;
create policy profile_self on profiles for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy submissions_self on task_submissions for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy enrollments_self on path_enrollments for all using (user_id = auth.uid()) with check (user_id = auth.uid());
